import type { JobDef, OperationDef } from "./types";

/**
 * Formatting and job-graph helpers for the manager planning flow.
 *
 * This module used to hold a greedy list scheduler as well. It does not any
 * more: schedules are generated by the backend's scheduling engine through
 * `POST /api/v1/schedules`, so a second solver in the browser could only ever
 * disagree with the one whose output is actually stored and simulated. What is
 * left is the arithmetic the job builder needs, plus the two formatters every
 * view shares.
 */

/**
 * The sum of the first listed route for each operation.
 *
 * Compatible routes are alternatives, not work performed in parallel. The
 * builder presents the first route as its concise estimate; the backend still
 * selects the actual route when it generates a schedule.
 */
export function totalWorkMins(job: Pick<JobDef, "operations">): number {
    return job.operations.reduce((total, operation) => total + (primaryRoute(operation)?.durationMins ?? 0), 0);
}

export function primaryRoute(operation: OperationDef) {
    return operation.routes[0];
}

/** 135 -> "2h 15m". Durations and offsets are always shown relative to T+0. */
export function formatDuration(mins: number): string {
    const hours = Math.floor(mins / 60);
    const minutes = Math.round(mins % 60);
    if (hours === 0) return `${minutes}m`;
    if (minutes === 0) return `${hours}h`;
    return `${hours}h ${minutes}m`;
}

/**
 * Energy for display, in kWh. `null` is **not recorded**, never zero.
 *
 * The database is explicit that a null energy means the source this pairing
 * came from did not record one (an academic job-shop benchmark records duration
 * and nothing else), so cost reporting has to exclude it rather than count it
 * as drawing no power. Rendering it as "0 kWh" would quietly assert the one
 * thing the column says it does not know.
 */
export function formatEnergy(energy: string | null): string {
    if (energy === null || energy.trim() === "") return "Not recorded";
    const value = Number(energy);
    if (Number.isNaN(value)) return energy;
    return `${value.toLocaleString(undefined, { maximumFractionDigits: 2 })} kWh`;
}

/** 135 -> "T+2:15" */
export function formatOffset(mins: number): string {
    const hours = Math.floor(mins / 60);
    const minutes = Math.round(mins % 60);
    return `T+${hours}:${String(minutes).padStart(2, "0")}`;
}
